record Weather(String city, double temperatureC) {}

Weather weather(String city) throws JsonProcessingException {
    String key = "weather:v1:" + city.toLowerCase(Locale.ROOT);
    String cached = redis.opsForValue().get(key);
    if (cached != null) {
        return mapper.readValue(cached, Weather.class);
    }
    Weather fresh = provider.fetch(city);
    if (fresh == null) {
        throw new IllegalStateException("Weather response is empty");
    }
    redis.opsForValue().set(key, mapper.writeValueAsString(fresh),
            Duration.ofSeconds(300));
    return fresh;
}

spring.data.redis.host=${REDIS_HOST}
spring.data.redis.port=${REDIS_PORT}
spring.data.redis.username=${REDIS_USERNAME}
spring.data.redis.password=${REDIS_PASSWORD}
spring.data.redis.ssl.enabled=true
spring.data.redis.connect-timeout=2s
spring.data.redis.timeout=2s
